@layer reset, astryx-base, astryx-theme;

@layer reset {
@scope ([data-astryx-theme="raw"]) to ([data-astryx-theme]) {
  :where(h1, h2, h3, h4, h5, h6) {
    font-family: var(--font-family-heading);
    color: var(--color-text-primary);
  }

  :where(h1) {
    font-size: var(--text-heading-1-size);
    font-weight: var(--text-heading-1-weight);
    line-height: var(--text-heading-1-leading);
  }

  :where(h2) {
    font-size: var(--text-heading-2-size);
    font-weight: var(--text-heading-2-weight);
    line-height: var(--text-heading-2-leading);
  }

  :where(h3) {
    font-size: var(--text-heading-3-size);
    font-weight: var(--text-heading-3-weight);
    line-height: var(--text-heading-3-leading);
  }

  :where(h4) {
    font-size: var(--text-heading-4-size);
    font-weight: var(--text-heading-4-weight);
    line-height: var(--text-heading-4-leading);
  }

  :where(h5) {
    font-size: var(--text-heading-5-size);
    font-weight: var(--text-heading-5-weight);
    line-height: var(--text-heading-5-leading);
  }

  :where(h6) {
    font-size: var(--text-heading-6-size);
    font-weight: var(--text-heading-6-weight);
    line-height: var(--text-heading-6-leading);
  }

  :where(p) {
    font-family: var(--font-family-body);
    font-size: var(--text-body-size);
    font-weight: var(--text-body-weight);
    line-height: var(--text-body-leading);
    color: var(--color-text-primary);
  }

  :where(small) {
    font-size: var(--text-supporting-size);
    font-weight: var(--text-supporting-weight);
    line-height: var(--text-supporting-leading);
    color: var(--color-text-secondary);
  }

  :where(code, pre) {
    font-family: var(--font-family-code);
    font-size: var(--text-code-size);
    line-height: var(--text-code-leading);
  }

  :where(hr) {
    border: none;
    border-top: 1px solid var(--color-border);
  }
}
}

@layer astryx-theme {
  :root { color-scheme: light dark; }
  html[data-theme="light"] { color-scheme: light; }
  html[data-theme="dark"] { color-scheme: dark; }

@scope ([data-astryx-theme="raw"]) to ([data-astryx-theme]) {
  :scope {
    --color-accent: light-dark(#7131E3, #DAB8FF);
    --color-accent-muted: light-dark(color-mix(in srgb, var(--color-accent) 20%, transparent), color-mix(in srgb, var(--color-accent) 25%, transparent));
    --color-on-accent: light-dark(#FFFFFF, #2C00AA);
    --color-neutral: light-dark(#1D1A211A, #E5E1EA33);
    --color-background-surface: light-dark(#FEFBFF, #1D1A21);
    --color-background-body: light-dark(#F4EFF8, #130F17);
    --color-overlay: light-dark(#1D1A2166, #1D1A2199);
    --color-overlay-hover: light-dark(#1D1A210D, #FFFFFF0D);
    --color-overlay-pressed: light-dark(#1D1A211A, #FFFFFF1A);
    --color-background-muted: light-dark(#1D1A210D, #1D1A2180);
    --color-text-primary: light-dark(#1D1A21, #E5E1EA);
    --color-text-secondary: light-dark(#4A4450, #AFA9B6);
    --color-text-disabled: light-dark(#958E9B, #625C68);
    --color-text-accent: var(--color-accent);
    --color-icon-accent: var(--color-accent);
    --color-icon-primary: light-dark(#1D1A21, #E5E1EA);
    --color-icon-secondary: light-dark(#4A4450, #AFA9B6);
    --color-icon-disabled: light-dark(#958E9B, #625C68);
    --color-background-card: light-dark(#FEFBFF, #1D1A21);
    --color-background-popover: light-dark(#FEFBFF, #322F36);
    --color-background-inverted: light-dark(#1D1A21, #FEFBFF);
    --color-border: light-dark(#1D1A211A, #F4EFF81A);
    --color-border-emphasized: light-dark(#958E9B, #6C6672);
    --color-skeleton: light-dark(#AFA9B6, #4A4450);
    --color-track: light-dark(#AFA9B6, #4A4450);
    --color-shadow: light-dark(#0000001A, #0000004D);
    --color-tint-hover: light-dark(black, white);
    --color-bg: #fff;
    --color-text-info: light-dark(#0064E0, #2A80FE);
    --color-text-success: light-dark(#0D8626, #2A9738);
    --color-text-warning: light-dark(#916E1B, #F2C00B);
    --color-text-error: light-dark(#E3193B, #F5394F);
    --color-on-info-muted: light-dark(#0E5ECB, #609CF8);
    --color-on-success-muted: light-dark(#09731F, #47B051);
    --color-on-warning-muted: light-dark(#866408, #F2C00B);
    --color-on-error-muted: light-dark(#BE022C, #FC6A70);
    --color-icon-info: var(--color-text-info);
    --color-icon-success: var(--color-text-success);
    --color-icon-warning: var(--color-text-warning);
    --color-icon-error: var(--color-text-error);
    --color-border-info: var(--color-text-info);
    --color-border-success: var(--color-text-success);
    --color-border-warning: var(--color-text-warning);
    --color-border-error: var(--color-text-error);
  }
}
}

@layer astryx-theme {
@scope ([data-astryx-theme="raw"]) to ([data-astryx-theme]) {
  [data-astryx-media="dark"] {
    color-scheme: dark;
    --color-text-primary: var(--color-on-dark);
    --color-icon-primary: var(--color-on-dark);
    --color-accent: var(--color-on-dark);
  }

  [data-astryx-media="light"] {
    color-scheme: light;
    --color-text-primary: var(--color-on-light);
    --color-icon-primary: var(--color-on-light);
    --color-accent: var(--color-on-light);
  }
}
}

